var EXTRA=[{"dot": "gray", "j": "Arthroscopy Techniques", "h": "Sutura meniscale continua ibrida: un impianto all-inside, più punti outside-in", "v": "Nota tecnica senza dati clinici: il filo libero dell'impianto all-inside viene ripassato per via percutanea in più punti outside-in; risparmio di impianti e stabilità sono dichiarati dagli autori, non misurati.", "pmid": "42831213", "doi": "10.1002/atn2.70265", "temi": ["sutura meniscale", "tecnica chirurgica", "menisco"]}, {"dot": "gray", "j": "Arthroscopy Techniques", "h": "Osteocondrite dissecante instabile dell'adolescente: fissazione artroscopica con osso spongioso strutturale", "v": "Nota tecnica passo-passo con innesto tibiale a striscia per difetti subcondrali estesi; nessun esito riportato, solo la descrizione del gesto.", "pmid": "42831113", "doi": "10.1002/atn2.70261", "temi": ["osteocondrite dissecante", "adolescente", "cartilagine"]}, {"dot": "gray", "j": "Arthroplasty Today", "h": "UKA mediale con taglio femorale per primo e allineamento cinematico calibrato", "v": "Nota tecnica: si ricostruisce prima la superficie femorale, poi la tibia con la pendenza nativa; il vantaggio dichiarato è la riproducibilità del posizionamento, non dimostrato da dati.", "pmid": "42831181", "doi": "10.1016/j.artd.2026.102147", "temi": ["protesi monocompartimentale", "allineamento cinematico", "pendenza tibiale"]}, {"dot": "gray", "j": "Arthroscopy", "h": "Instabilità rotulea: tempo di ritirare le soglie fisse di TT-TG", "v": "Commento editoriale di Mayo Clinic: le soglie storiche vanno almeno aggiustate per altezza e sesso, in prospettiva superate da una valutazione individuale; è un parere, non uno studio.", "pmid": "42832252", "doi": "10.1002/arj.70665", "temi": ["instabilità rotulea", "MPFL", "TT-TG"]}, {"dot": "gray", "j": "Sports Medicine - Open", "h": "Calcio femminile dopo LCA: paura e poco sostegno sociale frenano il rientro", "v": "Revisione di scoping su pochi studi: incertezza, paura e scarsa fiducia come barriere al ritorno al livello precedente; l'abstract non quantifica nulla e gli autori chiedono studi di qualità.", "pmid": "42828697", "doi": "10.1186/s40798-026-01118-6", "temi": ["ritorno allo sport", "LCA", "fattori psicosociali"]}, {"dot": "gray", "j": "Arthroplasty Today", "h": "Cinesiofobia dopo protesi totale: riabilitazione e terapia cognitivo-comportamentale la riducono", "v": "Meta-analisi di RCT: gli effetti sulla scala TSK si avvicinano alla soglia di rilevanza clinica, con certezza moderata per riabilitazione e bassa per terapia cognitivo-comportamentale; per altri interventi l'eterogeneità impedisce di sommare i dati.", "pmid": "42831041", "doi": "10.1016/j.artd.2026.102067", "temi": ["cinesiofobia", "protesi totale", "riabilitazione"]}, {"dot": "gray", "j": "EFORT Open Reviews", "h": "UKA da una parte e TKA dall'altra nello stesso paziente: revisione sistematica di D'Ambrosi", "v": "Abstract non disponibile su PubMed: titolo, rivista e autori verificati, contenuto non letto; è il gruppo del Galeazzi, già nella tua rete, e il tema è la scelta dell'impianto nell'artrosi bilaterale.", "pmid": "42825407", "doi": "10.1530/EOR-2025-0193", "temi": ["protesi monocompartimentale", "protesi totale", "artrosi bilaterale"]}, {"dot": "gray", "j": "Indian Journal of Orthopaedics", "h": "Conversione di UKA in TKA: esiti più vicini a una revisione che a una protesi primaria", "v": "Serie monocentrica abbinata, pochi pazienti: serve un componente di revisione sulla tibia in tutti i casi e i punteggi restano sotto quelli della protesi primaria; campione piccolo e follow-up breve.", "pmid": "42824250", "doi": "10.1007/s43465-026-01831-0", "temi": ["protesi monocompartimentale", "conversione", "revisione"]}, {"dot": "gray", "j": "Sensors", "h": "Dopo il LCA, il deficit di forza eccentrica emerge nella squat con volano", "v": "Studio trasversale su atleti di squadra: la fase eccentrica mostra un deficit nel lato operato che l'analisi globale non vede; campione molto piccolo e misure elettromiografiche esplorative.", "pmid": "42817281", "doi": "10.3390/s26185745", "temi": ["LCA", "forza eccentrica", "ritorno allo sport"]}];

var SCOPERTE=[{"t": "Dalla radiografia al calcolo automatico: la larghezza della fossa intercondiloidea misurata dall'algoritmo", "v": "Un gruppo giapponese ha costruito un sistema automatico per misurare il Notch Width Index, marcatore radiografico del rischio di LCA: l'accordo con due chirurghi è da moderato a buono (ICC 0,525-0,756; Dice di segmentazione 0,975), contro una riproducibilità manuale scarsa o moderata (ICC 0,475 e 0,562), su 33 radiografie. Vale la deviazione perché mostra dove l'intelligenza artificiale aiuta davvero in ortopedia, cioè nel rendere riproducibile una misura; sono 33 immagini, e fuori dal set di addestramento la segmentazione peggiora nelle ginocchia artrosiche.", "pmid": "42833019", "doi": "10.1016/j.knee.2026.104650", "temi": ["intelligenza artificiale", "LCA", "radiografia"]}, {"t": "Un impianto stampato in 3D per la cartilagine che non si riassorbe: capra, 16 settimane, e un limite dichiarato", "v": "Uno studio preclinico (Cartilage) su sei capre mette una struttura acellulare in nylon 12 stampata in 3D insieme alla microfrattura: con la versione al 45% di riempimento il punteggio istologico ICRS II mediano sale da 33 a 44 (p<0,05), ma l'analisi istologica riguarda tre difetti per gruppo e il patologo non era in cieco. Vale la deviazione perché è il terreno della bioingegneria sul quale lavorano AMIC e minced cartilage; il materiale non si riassorbe e provoca una reazione da corpo estraneo cronica, un limite che gli autori stessi indicano.", "pmid": "42817817", "doi": "10.1177/19476035261487354", "temi": ["cartilagine", "bioingegneria", "microfrattura"]}, {"t": "I farmaci anti-CGRP per l'emicrania e l'osso: che cosa dice la revisione di scoping sul ginocchio", "v": "Una revisione di scoping su studi preclinici e pochi dati umani riporta che il CGRP favorisce la guarigione ossea e partecipa alla sensibilizzazione dolorosa nell'artrosi; l'unico RCT citato, con l'anticorpo galcanezumab, non ha ridotto segni e sintomi dell'artrosi del ginocchio. Vale la deviazione perché un farmaco largamente prescritto per un'altra malattia potrebbe incontrare i tuoi pazienti; le prove umane sono per lo più biomarcatori e casi clinici, e gli autori non vedono ragioni per modificare la terapia.", "pmid": "42820961", "doi": "10.1007/s00223-026-01619-2", "temi": ["farmaci", "artrosi", "guarigione ossea"]}];

var SOC={"1": {"video": "Aggiungere un preparato biologico all'intervento al crociato aiuta la guarigione? Una revisione di nove studi randomizzati, su 543 pazienti, ha provato a rispondere.\n\nI preparati erano plasma ricco di piastrine, midollo osseo concentrato e cellule staminali. I punteggi di funzione del ginocchio e la guarigione del tunnel nell'osso non erano diversi con o senza il preparato. Nessuna complicanza riportata.\n\nIl limite: gli studi sono pochi e diversi fra loro, quindi non si può dire che il biologico non serva mai, ma un vantaggio non è stato dimostrato.\nFonte: PubMed, PMID 42832231.", "linkedin": "Biologici nell'aumento della ricostruzione del LCA (Arthroscopy, ottobre 2026): revisione sistematica e meta-analisi di RCT, livello II, 9 studi e 543 pazienti con PRP (5), BMAC (3) e cellule staminali mesenchimali (1).\n\nPRP: Lysholm SMD 0,99 (0,72-1,36; p=0,95). BMAC: KOOS 0,78 (0,41-1,49; p=0,45). Allargamento del tunnel 1,56 (0,61-3,96; p=0,35). Maturazione dell'innesto: in 6 studi su 9 nessun cambiamento significativo. Nessuna complicanza riportata.\n\nLimite: I² 77% e 87%, pochi studi per biologico, intervalli che contengono 1 e non 0 come valore nullo, nessun esito duro; tipo di innesto non riportato nell'abstract. Nessuna differenza non è equivalenza.\nFonte: PubMed, PMID 42832231.", "instagram": "Biologici nel crociato: servono?\nNove studi, 543 pazienti: punteggi del ginocchio e guarigione dell'osso simili con e senza il preparato.\n\nStudi pochi e diversi: un vantaggio non è dimostrato, ma non è nemmeno escluso.\nFonte: PubMed, PMID 42832231.", "pazienti": "Alcuni interventi al legamento crociato aggiungono un preparato ricavato dal sangue o dal midollo osseo del paziente, nella speranza di favorire la guarigione.\n\nUna revisione di nove studi su 543 pazienti ha confrontato chi lo riceveva con chi non lo riceveva: i punteggi del ginocchio e la guarigione dell'osso sono risultati simili.\n\nGli studi sono pochi e diversi tra loro, quindi se ne parla con il chirurgo, caso per caso.\nFonte: PubMed, PMID 42832231."}};

var SOCV={"1": {"video": {"chir": ["Aumentare la ricostruzione del LCA con un biologico: serve? Una meta-analisi di nove RCT, 543 pazienti, su Arthroscopy, ottobre 2026, ha messo insieme PRP, aspirato di midollo concentrato e cellule staminali mesenchimali.", "Il PRP non cambia il Lysholm, il BMAC non cambia il KOOS, l'allargamento del tunnel non cambia: p da 0,35 a 0,95. In sei studi su nove la maturazione dell'innesto è simile. Nessuna complicanza riportata.", "Il limite: eterogeneità alta, I² 77% e 87%, tre biologici con pochi studi ciascuno, nessun esito duro nell'abstract; nessuna differenza non è equivalenza. Intervalli esposti su una scala poco chiara.\nFonte: PubMed, PMID 42832231."], "misto": ["Aggiungere un preparato biologico all'intervento al crociato aiuta la guarigione? Una revisione di nove studi randomizzati, su 543 pazienti, ha provato a rispondere.", "I preparati erano plasma ricco di piastrine, midollo osseo concentrato e cellule staminali. I punteggi di funzione del ginocchio e la guarigione del tunnel nell'osso non erano diversi con o senza il preparato. Nessuna complicanza riportata.", "Il limite: gli studi sono pochi e diversi fra loro, quindi non si può dire che il biologico non serva mai, ma un vantaggio non è stato dimostrato.\nFonte: PubMed, PMID 42832231."], "pazienti": ["Alcuni interventi al legamento crociato aggiungono un preparato ricavato dal sangue o dal midollo osseo del paziente. Serve davvero?", "Una revisione di nove studi, con 543 pazienti, non ha trovato differenze nei punteggi del ginocchio né nella guarigione dell'osso fra chi lo riceveva e chi no.", "Gli studi sono pochi e diversi tra loro: la scelta si discute con il chirurgo.\nFonte: PubMed, PMID 42832231."]}, "linkedin": {"chir": ["Biologici nell'aumento della ricostruzione del LCA (Arthroscopy, ottobre 2026): revisione sistematica e meta-analisi di RCT, livello II, 9 studi e 543 pazienti con PRP (5), BMAC (3) e cellule staminali mesenchimali (1).", "PRP: Lysholm SMD 0,99 (0,72-1,36; p=0,95). BMAC: KOOS 0,78 (0,41-1,49; p=0,45). Allargamento del tunnel 1,56 (0,61-3,96; p=0,35). Maturazione dell'innesto: in 6 studi su 9 nessun cambiamento significativo. Nessuna complicanza riportata.", "Limite: I² 77% e 87%, pochi studi per biologico, intervalli che contengono 1 e non 0 come valore nullo, nessun esito duro; tipo di innesto non riportato nell'abstract. Nessuna differenza non è equivalenza.\nFonte: PubMed, PMID 42832231."], "misto": ["Biologici nella ricostruzione del crociato: una meta-analisi di nove studi randomizzati (Arthroscopy, ottobre 2026), 543 pazienti, con plasma ricco di piastrine, midollo osseo concentrato e cellule staminali.", "Funzione del ginocchio e guarigione del tunnel nell'osso non erano diverse con o senza il preparato; in 6 studi su 9 anche la maturazione dell'innesto era simile; nessuna complicanza riportata.", "Limite: studi pochi, diversi e con risultati molto variabili; un vantaggio non è dimostrato, ma non è nemmeno escluso.\nFonte: PubMed, PMID 42832231."], "pazienti": ["Preparati biologici durante l'intervento al legamento crociato: una revisione di nove studi su 543 pazienti.", "Punteggi del ginocchio e guarigione dell'osso risultano simili con e senza il preparato, e non sono state riportate complicanze.", "Gli studi sono pochi e diversi: se ne parla con lo specialista.\nFonte: PubMed, PMID 42832231."]}, "instagram": {"chir": ["Biologici nel LCA: nove RCT, 543 pazienti.", "PRP, BMAC, cellule staminali: Lysholm, KOOS e tunnel senza differenza (p 0,35-0,95).", "Limite: I² 77% e 87%, nessun esito duro.\nFonte: PubMed, PMID 42832231."], "misto": ["Biologici nel crociato: servono?", "Nove studi, 543 pazienti: punteggi e guarigione dell'osso simili con e senza.", "Studi pochi e diversi: un vantaggio non è dimostrato.\nFonte: PubMed, PMID 42832231."], "pazienti": ["Crociato: aggiungere un preparato biologico non ha mostrato vantaggi.", "Nove studi, 543 pazienti: risultati simili con e senza.", "Studi pochi e diversi: se ne parla con il chirurgo.\nFonte: PubMed, PMID 42832231."]}, "reel": {"chir": ["LCA e biologici: nove RCT.", "PRP, BMAC, staminali: nessun vantaggio su Lysholm, KOOS, tunnel.", "Eterogeneità alta, nessun esito duro."], "misto": ["Biologici nel crociato: servono?", "Nove studi: stessi risultati con e senza il preparato.", "Un vantaggio non è dimostrato."], "pazienti": ["Crociato e preparati biologici.", "Nove studi: risultati simili con e senza.", "Se ne parla con il chirurgo."]}}};

var TAGS={"1": {"linkedin": "#Ortopedia #LCA #MedicinaBasataSulleProve", "instagram": "#ortopedia #ginocchio #legamentocrociato #lca #biologici #prp #medicinarigenerativa #ortopediaticino #medicinabasatasulleprove #traumatologiadellosport", "kw": "legamento crociato anteriore, plasma ricco di piastrine, cellule staminali ginocchio"}};

var NLB={"1": {"prof": ["Biologici nell'aumento del LCA: nove RCT senza vantaggio su punteggi né su tunnel", "Una meta-analisi di RCT (Arthroscopy, ottobre 2026) su 9 studi e 543 pazienti confronta la ricostruzione del LCA con e senza biologici: PRP (5 studi), aspirato di midollo concentrato BMAC (3) e cellule staminali mesenchimali (1). Per il PRP il Lysholm non differisce (SMD 0,99; IC 0,72-1,36; p=0,95); per il BMAC non differisce il KOOS (0,78; 0,41-1,49; p=0,45); l'allargamento del tunnel non cambia (1,56; 0,61-3,96; p=0,35). In 6 studi su 9 la maturazione dell'innesto non cambia in modo significativo; nessuna complicanza riportata.", "Nota critica: eterogeneità alta (I² 77% e 87%), tre biologici diversi con pochi studi ciascuno, intervalli esposti su una scala poco chiara nell'abstract e nessun esito duro; l'assenza di differenza non equivale a equivalenza."], "mix": ["Biologici nella ricostruzione del crociato: nove studi randomizzati non mostrano un vantaggio", "Una revisione di nove studi randomizzati, con 543 pazienti, ha esaminato se aggiungere alla ricostruzione del legamento crociato un preparato biologico (plasma ricco di piastrine, midollo osseo concentrato o cellule staminali) migliori i punteggi riferiti dai pazienti o la guarigione dell'innesto. I punteggi di funzione (Lysholm per il plasma, KOOS per il midollo) e l'allargamento del tunnel osseo non sono risultati diversi con o senza il biologico (p da 0,35 a 0,95), e in 6 studi su 9 anche la maturazione dell'innesto all'imaging era simile. Non sono state riportate complicanze legate ai preparati.", "Nota sul limite: gli studi sono pochi, diversi fra loro e con risultati molto variabili; non vuol dire che il biologico non serva in assoluto, ma che un vantaggio non è stato dimostrato."], "paz": ["Crociato: aggiungere preparati biologici all'intervento non ha mostrato un vantaggio", "Alcuni interventi al legamento crociato aggiungono un preparato ricavato dal sangue o dal midollo osseo del paziente, nella speranza di favorire la guarigione. Una revisione di nove studi su 543 pazienti ha confrontato chi lo riceveva con chi non lo riceveva: i punteggi del ginocchio e la guarigione del tunnel nell'osso sono risultati simili nei due gruppi. Non sono state riportate complicanze legate a questi preparati.", "Gli studi sono pochi e differenti tra loro, quindi non si può dire che questi preparati non servano mai: la scelta si discute con il chirurgo, caso per caso."], "kw": "legamento crociato anteriore, plasma ricco di piastrine, cellule staminali ginocchio, ricostruzione crociato"}, "2": {"prof": ["Radice meniscale: riparazione associata a esiti migliori, ma senza protocollo condiviso", "Una revisione narrativa sul Journal of Bone and Joint Surgery (ottobre 2026) riassume epidemiologia, diagnosi e trattamento delle lesioni radicolari del menisco. Le lesioni compromettono la distribuzione dei carichi e accelerano l'artrosi; nei pazienti selezionati la riparazione si associa a esiti a lungo termine migliori della meniscectomia parziale e del trattamento non operatorio. Non esiste un protocollo riabilitativo universale: la maggior parte delle strategie limita il carico nelle prime settimane e la flessione sotto carico, come lo squat profondo, fino a 4-5 mesi.", "Nota critica: revisione narrativa; l'abstract non riporta il numero di studi né le dimensioni dell'effetto e non dice quanto del confronto con la meniscectomia poggi su dati osservazionali."], "mix": ["Lesioni della radice del menisco: la riparazione sembra dare risultati migliori nel tempo", "Una revisione pubblicata sul Journal of Bone and Joint Surgery riassume che cosa si sa sulle lesioni della radice del menisco, il punto in cui il menisco si ancora all'osso. Quando la radice non regge, il menisco non distribuisce più i carichi e la cartilagine si consuma più in fretta. Nei pazienti ben selezionati la riparazione si associa a risultati migliori nel lungo periodo rispetto all'asportazione parziale e al trattamento senza intervento. Dopo la riparazione non esiste un protocollo unico: di solito si limita il carico all'inizio e per circa 4-5 mesi si evita di piegare il ginocchio sotto peso, per esempio accovacciandosi.", "Nota sul limite: è una revisione narrativa, senza numeri nell'abstract; non dice di quanto sia migliore la riparazione né per chi in particolare."], "paz": ["Lesione della radice del menisco: quando possibile si cerca di riparare invece di asportare", "La radice del menisco è il punto in cui il menisco si fissa all'osso: se si lesiona, il menisco non assorbe più bene i carichi e la cartilagine tende a usurarsi. Secondo una revisione degli studi, nei pazienti adatti la riparazione si associa a risultati migliori nel tempo rispetto all'asportazione di una parte del menisco o alla sola terapia senza intervento. Dopo la riparazione si limita il carico e si evita di piegare molto il ginocchio sotto peso per circa quattro-cinque mesi, ma i protocolli non sono ancora uguali ovunque.", "La scelta dipende da età, attività e stato della cartilagine: se ne parla con lo specialista, perché la revisione non dà percentuali."], "kw": "lesione radice menisco, sutura del menisco, menisco ginocchio, riabilitazione dopo sutura meniscale"}, "3": {"prof": ["UKA dopo HTO fallita: revisioni 10,2% contro 5,0% della TKA, confronto solo indiretto", "Una meta-analisi (Arthroplasty, ottobre 2026) di 41 studi, quasi tutti osservazionali, descrive gli esiti dopo osteotomia tibiale alta fallita. Con la protesi monocompartimentale la revisione è 10,2% (IC 95% 4,5-21,6; 226 ginocchia) e il reintervento 14,4% (9,1-21,9); con la protesi totale la revisione è 5,0% (3,5-7,2; 6208 ginocchia) e il reintervento 11,1% (7,3-16,3). I due studi comparativi diretti non trovano differenze significative di sopravvivenza o funzione; la causa più frequente di revisione della UKA è la progressione laterale.", "Nota critica: confronto indiretto e gruppi sbilanciati (226 contro oltre 6000), eterogeneità alta nella TKA (I² 79,5% e 92,8%); gli autori stessi lo leggono come generatore di ipotesi, non come equivalenza."], "mix": ["Dopo un'osteotomia tibiale fallita, la protesi parziale può essere un'opzione in casi scelti", "Una revisione di 41 studi ha raccolto gli esiti delle protesi al ginocchio impiantate dopo il fallimento di un'osteotomia tibiale alta. La protesi parziale è stata rimossa o rifatta nel 10,2% dei casi (intervallo 4,5-21,6%, su 226 ginocchia), la totale nel 5,0% (3,5-7,2%, su oltre seimila ginocchia); la causa più frequente per la parziale è l'avanzare dell'artrosi nel compartimento laterale. Nei soli due studi che le confrontano direttamente non emergono differenze significative. Gli autori ritengono che la protesi parziale non vada esclusa a priori in pazienti selezionati, con artrosi limitata al lato interno, legamento collaterale mediale integro e allineamento residuo accettabile.", "Nota sul limite: i casi di protesi parziale sono pochi e quasi tutti da studi retrospettivi, quindi non si può dire che le due protesi siano equivalenti."], "paz": ["Dopo un'osteotomia al ginocchio, una protesi parziale può essere valutata in alcuni casi", "A volte l'osteotomia, l'intervento che corregge l'asse della gamba, con il tempo non basta più e serve una protesi. Una revisione di 41 studi ha raccolto i risultati sia della protesi totale sia di quella parziale in questa situazione. La protesi parziale è stata sostituita o rifatta più spesso di quella totale (10,2% contro 5,0%), ma i dati sulla parziale sono molto meno numerosi. Gli autori ritengono che possa essere considerata in pazienti ben selezionati.", "Lo studio non permette di dire quale protesi sia meglio: la scelta dipende dal tipo di artrosi e dallo stato dei legamenti, e si discute con lo specialista."], "kw": "osteotomia tibiale alta, protesi monocompartimentale, protesi ginocchio dopo osteotomia, artrosi ginocchio"}, "4": {"prof": ["LCA con peroneo lungo o hamstring: prelievo di 7 contro 24 minuti, Lysholm uguale a 12 mesi", "Un RCT monocentrico (The Surgeon, ottobre 2026; Kano, Nigeria) su 162 adulti, 81 per braccio, confronta il tendine peroneo lungo con l'hamstring nella ricostruzione del LCA. Il prelievo richiede 7,13 ± 2,30 minuti contro 24,37 ± 4,85 (p<0,05) e l'innesto è più lungo e più spesso; il Lysholm a 12 mesi non differisce (p=0,53). Nel braccio hamstring si osservano ipotrofia della coscia e un'infezione del sito chirurgico; l'AOFAS del braccio peroneo torna vicino al basale a 6 mesi.", "Nota critica: 12 mesi, un solo centro, nessun esito duro nell'abstract e randomizzazione non descritta; l'assenza di differenza sul Lysholm, senza IC, non dimostra equivalenza. Non è l'innesto quadricipitale."], "mix": ["Crociato: il tendine del peroneo come alternativa ai tendini della coscia, risultati simili a un anno", "In uno studio randomizzato in Nigeria, 162 adulti operati di crociato anteriore hanno ricevuto un innesto prelevato dal tendine del peroneo lungo, vicino alla caviglia, oppure dai tendini della coscia. Il prelievo è stato molto più rapido (circa 7 minuti contro 24) e l'innesto più lungo e più spesso; a un anno il punteggio del ginocchio (Lysholm) era simile nei due gruppi. Dopo il prelievo dalla coscia si è osservata una riduzione di volume del muscolo; dopo quello dal peroneo la funzione della caviglia è tornata quasi al livello di partenza entro sei mesi.", "Nota sul limite: lo studio dura un anno e viene da un solo centro; non dice nulla sulla tenuta a lungo termine dell'innesto né sul ritorno allo sport."], "paz": ["Legamento crociato: un tendine della gamba come alternativa a quelli della coscia", "Per ricostruire il legamento crociato si usa un tendine prelevato dal paziente. In uno studio su 162 adulti, un gruppo ha ricevuto un tendine della gamba, vicino alla caviglia, l'altro i tendini della coscia. Il prelievo dalla gamba è stato più veloce e a un anno i punteggi del ginocchio erano simili. Dopo il prelievo dalla coscia i muscoli risultavano più sottili; la funzione della caviglia, dopo il prelievo dalla gamba, è tornata quasi al livello di partenza entro sei mesi.", "Lo studio segue i pazienti solo per un anno: non dice come l'innesto regge nel tempo. La scelta dell'innesto si discute con il chirurgo."], "kw": "ricostruzione legamento crociato anteriore, innesto tendineo, prelievo tendine, recupero dopo operazione crociato"}, "5": {"prof": ["TKA convenzionale, MAKO o sensori di pressione: nessun esito con differenza dopo correzione", "Una coorte retrospettiva monocentrica (Journal of Robotic Surgery, settembre 2026) su 173 ginocchia in 139 pazienti confronta la protesi totale con conservazione del crociato posteriore eseguita con strumentario convenzionale (36), con assistenza robotica MAKO (92) e con sensore di pressione Verasense (45). Dopo correzione di Holm nessun esito differisce fra i gruppi; Verasense contro MAKO mostra un dolore aggiustato inferiore di 0,318 punti (p di Holm 0,2546). Il dolore postoperatorio è zero in 125 ginocchia su 149 (83,9%).", "Nota critica: retrospettivo, 36 ginocchia nel gruppo convenzionale, assegnazione non randomizzata e IC non riportati; non è prova di equivalenza. È coerente, in modo debole, con RACER-Knee."], "mix": ["Protesi totale: tecnica convenzionale, robot o sensori di pressione, esiti simili in un centro di Hong Kong", "In un centro di Hong Kong 173 protesi totali di ginocchio, eseguite con strumenti tradizionali, con assistenza robotica o con un sensore che misura la pressione nell'articolazione, sono state confrontate dopo l'intervento per dolore, mobilità e funzione. Una volta applicata la correzione statistica per i confronti multipli, nessuna differenza è risultata significativa. In quasi 84 ginocchia su 100 il dolore dopo l'intervento era assente.", "Nota sul limite: lo studio guarda indietro nel tempo, il gruppo con tecnica tradizionale è piccolo e i pazienti non sono stati assegnati a caso: non dimostra che le tre tecniche siano equivalenti."], "paz": ["Protesi al ginocchio: con o senza robot, i risultati in un centro erano simili", "In un ospedale di Hong Kong sono state confrontate tre modalità di impianto della protesi totale di ginocchio: strumenti tradizionali, robot e un sensore che misura la pressione. Nei 173 ginocchi studiati non sono emerse differenze affidabili su dolore, movimento e funzione. Dopo l'intervento il dolore era assente in gran parte dei casi.", "Lo studio è piccolo e guarda al passato: non dice che le tre tecniche siano uguali, solo che qui non sono state trovate differenze nette."], "kw": "protesi totale ginocchio, chirurgia robotica ginocchio, dolore dopo protesi, artroprotesi"}, "6": {"prof": ["RM prima del crociato: un marcatore di cartilagine e menisco si associa ai sintomi a 11 anni", "Una coorte retrospettiva su 22 pazienti con LCA ricostruito (Journal of Magnetic Resonance Imaging, ottobre 2026) confronta la RM con sequenza UTE-T2* prima dell'intervento con i punteggi a una mediana di 11,3 anni. UTE-T2* più alto nella cartilagine femorale mediale profonda e nel menisco mediale si associa a KOOS Sintomi peggiore (R² aggiustato 0,146-0,332); nelle 11 radiografie disponibili il valore del menisco posteriore era più alto del 69% con artrosi radiografica. Per il menisco posteriore l'associazione con il livello di attività va in senso opposto.", "Nota critica: 22 pazienti, IC non riportati e nessuna correzione per test multipli dichiarata; l'analisi è esplorativa e non dice se il marcatore migliori la previsione rispetto alla RM convenzionale."], "mix": ["Prima dell'intervento al crociato, la RM può già dare indizi sui sintomi a distanza di 11 anni", "In uno studio su 22 persone operate di legamento crociato, una RM speciale eseguita prima dell'intervento misurava la composizione della cartilagine e del menisco. Chi aveva valori più alti in alcune zone del lato interno del ginocchio riferiva più sintomi a undici anni di distanza. Nelle 11 persone con radiografie, il valore del menisco posteriore era più alto del 69% in chi aveva già segni di artrosi.", "Nota sul limite: il campione è molto piccolo e i dati sono preliminari; non si possono usare oggi per decidere una cura, e i risultati non vanno in un'unica direzione."], "paz": ["Una RM particolare prima dell'operazione potrebbe aiutare a capire come andrà il ginocchio negli anni", "Uno studio su 22 persone operate al legamento crociato ha provato a vedere se una risonanza speciale, fatta prima dell'intervento, potesse dire qualcosa sui sintomi dopo undici anni. In alcune zone del ginocchio, valori più alti si associavano a più disturbi. Sono dati preliminari, su pochissime persone.", "Non è un esame che si usa oggi per decidere la cura: la ricerca serve a capire se in futuro potrà aiutare."], "kw": "legamento crociato anteriore, risonanza magnetica ginocchio, cartilagine, artrosi dopo crociato"}, "7": {"prof": ["Crociato e salute mentale: la diagnosi preesistente pesa sul KOOS solo a 2 settimane", "Una coorte retrospettiva (Sports Health, ottobre 2026) su 365 adulti operati di LCA tra il 2016 e il 2023 confronta i pazienti con diagnosi di salute mentale preesistente (50, 13,7%) con gli altri. Il KOOS è peggiore a 2 settimane nel gruppo con diagnosi e non differisce dopo. Fra i 315 senza storia, 8 (2,5%) hanno ricevuto una nuova diagnosi entro 1 anno, più spesso dopo infortuni non sportivi (7% contro 1,6%; p=0,02).", "Nota critica: retrospettivo, diagnosi ricavate da cartella, soli 8 eventi nuovi e IC non riportati; «nessuna differenza dopo 2 settimane» non è prova di equivalenza."], "mix": ["Dopo l'intervento al crociato, chi aveva già disturbi psicologici recupera in modo simile dopo due settimane", "Uno studio su 365 adulti operati di legamento crociato ha confrontato chi aveva già una diagnosi di ansia, depressione o altro disturbo psichico, circa 14 su 100, con chi non l'aveva. Il punteggio del ginocchio era peggiore solo nelle prime due settimane; dopo non c'erano differenze. Fra chi non aveva storia psichica, circa 2-3 su 100 hanno ricevuto una nuova diagnosi nell'anno, più spesso dopo un infortunio non sportivo (7 su 100 contro meno di 2).", "Nota sul limite: i nuovi casi sono pochissimi (otto in tutto) e i dati vengono da cartelle cliniche: indicano una direzione, non una misura precisa."], "paz": ["Dopo il crociato, un disturbo psicologico preesistente non ha rallentato il recupero oltre le prime settimane", "In uno studio su 365 adulti operati al legamento crociato, chi aveva già un disturbo come ansia o depressione ha avuto un punteggio del ginocchio peggiore soltanto nelle prime due settimane; dopo, i risultati erano simili a quelli degli altri. Dopo infortuni non legati allo sport è stato più frequente ricevere per la prima volta una diagnosi psicologica nell'anno successivo.", "I numeri sono piccoli e vengono da cartelle cliniche: se durante il recupero ci si sente giù, conviene dirlo al medico o al fisioterapista."], "kw": "legamento crociato anteriore, recupero dopo operazione, ansia depressione sport, riabilitazione ginocchio"}, "8": {"prof": ["Basi tibiali Triathlon: lo stelo centrale nella chiglia non cambia le revisioni (HR 1,05)", "Un'analisi del registro australiano AOANJRR (The Journal of Knee Surgery, ottobre 2026) su 76.710 TKA cementate minimamente stabilizzate, dal 1999 al 2023, confronta due basi tibiali Triathlon: con stelo centrale e alette, o solo con alette. La revisione complessiva non differisce (HR 1,05; IC 95% 0,74-1,48; p=0,779), né per mobilizzazione con i numeri disponibili; nelle donne con le sole alette HR 1,33 (1,01-1,75; p=0,045).", "Nota critica: l'intervallo non esclude un aumento fino a circa il 48% con le sole alette, il risultato nelle donne è un sottogruppo con p=0,045 e i dati di registro non sono randomizzati."], "mix": ["Protesi totale: uno stelo centrale sotto la tibia non cambia il rischio di nuovo intervento in un grande registro", "Un registro australiano ha confrontato su oltre 76.000 protesi totali di ginocchio due versioni della base che si fissa alla tibia: con uno stelo centrale più alette, oppure solo con alette. A cinque-sei anni, in media, la probabilità di dover rifare la protesi era simile con le due versioni, anche per mobilizzazione. Una differenza è comparsa soltanto nelle donne con la versione senza stelo.", "Nota sul limite: l'intervallo statistico non esclude differenze anche non piccole in entrambe le direzioni, da circa un quarto in meno a circa la metà in più; il dato sulle donne viene da un sottogruppo e va confermato."], "paz": ["Protesi di ginocchio: un dettaglio sotto la tibia non ha cambiato la durata dell'impianto in un registro", "Un grande registro australiano ha seguito oltre 76.000 persone con protesi totale di ginocchio per circa cinque anni e mezzo. Ha confrontato due modelli della parte che si fissa alla tibia, uno con un piccolo stelo centrale e uno senza. In media non sono state trovate differenze nel numero di protesi che hanno dovuto essere rifatte.", "Il registro non assegna i pazienti a caso e il periodo di osservazione è limitato: è una fotografia, non una prova definitiva."], "kw": "protesi totale ginocchio, durata della protesi, registro protesi, revisione protesi"}};

var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"Biologici nel LCA: nove RCT, nessun vantaggio su punteggi né su tunnel",v:"Meta-analisi di 9 RCT (543 pazienti) su PRP (5 studi), aspirato di midollo concentrato BMAC (3) e cellule staminali mesenchimali (1) come aumento della ricostruzione del LCA: PRP e Lysholm SMD 0,99 (IC 0,72-1,36; p=0,95), BMAC e KOOS 0,78 (0,41-1,49; p=0,45), allargamento del tunnel 1,56 (0,61-3,96; p=0,35); in 6 studi su 9 nessun cambiamento significativo della maturazione dell'innesto.",ax:"Driscoll, Mazzocco, Fucaloro, Sun, Bragg, Puzzitiello, Salzler",date:"ott 2026",meta:"revisione sistematica con meta-analisi di RCT, 9 studi, 543 pazienti · [II]",pmid:'42832231',doi:'10.1002/arj.70638',journal:"Arthroscopy : the journal of arthroscopic & related surgery : official publication of the Arthroscopy Association of North America and the International Arthroscopy Association",authors:"Driscoll A, Mazzocco J, Fucaloro S, Sun C, Bragg J, Puzzitiello R, Salzler MJ",design:"Revisione sistematica con meta-analisi secondo PRISMA (PubMed, EMBASE, Web of Science): RCT che confrontano esiti riferiti dal paziente o valutazione radiografica della maturazione dell'innesto dopo ricostruzione del LCA con e senza biologici (PRP, BMAC, cellule staminali mesenchimali); esclusi gli studi con il biologico applicato al sito di prelievo. Effetti casuali (DerSimonian-Laird), differenza media standardizzata, solo per gli esiti con almeno 3 studi sullo stesso biologico. Livello II secondo gli autori. Testo completo non aperto (non open access): numeri dall'abstract.",pop:"9 RCT, 543 pazienti in tutto: PRP in 5 studi, BMAC in 3, cellule staminali mesenchimali in 1. Tipo di innesto, età e durata del follow-up dei singoli studi: non riportati nell'abstract.",results:"PRP, Lysholm: SMD 0,99 (0,72-1,36; I² 0,58%; p=0,95). BMAC, KOOS: SMD 0,78 (0,41-1,49; I² 76,97%; p=0,45). Allargamento del tunnel osseo: SMD 1,56 (0,61-3,96; I² 87,46%; p=0,35). Maturazione radiografica dell'innesto valutata in tutti i 9 studi: in 6 nessun cambiamento significativo con il biologico. Nessuna complicanza da biologici riportata. Nota di lettura: i tre intervalli contengono 1 e non 0, come se fossero espressi su scala di rapporto, mentre una differenza media standardizzata nulla vale 0; l'abstract non lo chiarisce e senza il testo completo non è verificabile.",concl:"Gli autori: l'aumento biologico del LCA mostra esiti riferiti dal paziente e guarigione del tunnel simili alla sola ricostruzione; efficacia limitata e risultati gravati da eterogeneità.",limits:"Eterogeneità alta (I² 77% per il BMAC, 87% per il tunnel) e pochi studi: nessun sottogruppo supera 5 RCT, con tre biologici diversi · scala degli intervalli poco chiara (vedi sopra) · esiti duri (rottura dell'innesto, instabilità, rientro allo sport) non riportati nell'abstract; «nessuna differenza» non è equivalenza (vedi studio muto).",perte:"Non usi biologici per aumentare il LCA: il lavoro dice che un vantaggio non è dimostrato, non che sia escluso. Il tipo di innesto degli RCT non è riportato nell'abstract, quindi non si sa se valga per il tendine quadricipitale. Non muove nessuna tensione."},
{n:2,mono:"m-gray",dot:"green",sec:"res",j:"The Journal of Bone and Joint Surgery",h:"Radice meniscale: la riparazione si associa a esiti migliori, manca il protocollo",v:"Revisione narrativa (JBJS): nei pazienti selezionati la riparazione della radice si associa a esiti a lungo termine migliori della meniscectomia parziale e della terapia non operatoria; nessun protocollo riabilitativo condiviso, in genere carico limitato presto e flessione sotto carico (squat profondo) evitata fino a 4-5 mesi. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",ax:"Livingston, Ross, Saraf, Christiansen, Miller, Mulcahey",date:"ott 2026",meta:"revisione narrativa (epidemiologia, diagnosi, trattamento, esiti), numero di studi non riportato · [V]",pmid:'42832596',doi:'10.2106/JBJS.25.00800',journal:"The Journal of bone and joint surgery. American volume",authors:"Livingston M, Ross P, Saraf SM, Christiansen M, Miller JR, Mulcahey MK",design:"Revisione narrativa (punti chiave dell'abstract): epidemiologia, diagnosi, trattamento ed esiti delle lesioni radicolari del menisco. Strategia di ricerca e numero di studi inclusi: non riportati nell'abstract. Testo completo non aperto (non open access).",pop:"Non applicabile: revisione narrativa; nessuna popolazione riportata.",results:"Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: le lesioni radicolari compromettono la distribuzione dei carichi e accelerano la degenerazione cartilaginea; la diagnosi poggia sul sospetto clinico e sulla RM, con l'artroscopia come conferma; la scelta va adattata a età, attività, caratteristiche della lesione e grado di usura condrale; la riparazione è associata a esiti a lungo termine migliori della meniscectomia parziale e della terapia non operatoria in pazienti appropriati; manca un protocollo riabilitativo universale.",limits:"Revisione narrativa: nessun effetto quantificato nell'abstract e nessuna dichiarazione sul rischio di bias dei lavori citati · il confronto con la meniscectomia può poggiare su dati osservazionali con selezione dei pazienti: l'abstract non lo dichiara · tecnica di riparazione (transtibiale o altro) non specificata nell'abstract.",perte:"Rifissi la radice con tecnica transtibiale: la revisione sostiene l'indicazione alla riparazione in pazienti selezionati e conferma che non c'è un protocollo riabilitativo condiviso. Non dice nulla, nell'abstract, sull'estrusione o sul ritardo (T3): nessuna tensione si sposta."},
{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Arthroplasty",h:"UKA dopo HTO fallita: revisioni 10,2% contro 5,0% della TKA, confronto solo indiretto",v:"Meta-analisi di 41 studi, quasi tutti osservazionali: dopo HTO fallita la UKA ha revisione 10,2% (IC 95% 4,5-21,6; 226 ginocchia) e reintervento 14,4% (9,1-21,9); la TKA revisione 5,0% (3,5-7,2; 6208 ginocchia) e reintervento 11,1% (7,3-16,3). I 2 studi comparativi diretti non trovano differenze significative.",ax:"Vosoughi, Taghva Nakhjiri, Saghafi, Koolinia, Nikeghbali, Menbari Oskouie",date:"ott 2026",meta:"revisione sistematica con meta-analisi, 41 studi prevalentemente osservazionali, 226 UKA e 6208 TKA · [III]",pmid:'42830308',doi:'10.1186/s42836-026-00434-2',journal:"Arthroplasty (London, England)",authors:"Vosoughi F, Taghva Nakhjiri M, Saghafi AA, Koolinia F, Nikeghbali G, Menbari Oskouie I",design:"Revisione sistematica con meta-analisi (MEDLINE, Embase, Scopus, Web of Science fino al 14 agosto 2025): studi randomizzati e osservazionali con esiti di UKA o TKA dopo HTO; esclusi casi clinici, note tecniche, revisioni. Confronto UKA-TKA descrittivo/indiretto, dichiarato tale dagli autori. Livello III secondo gli autori. Testo completo non aperto.",pop:"41 studi: 6 solo UKA, 33 solo TKA, 2 comparativi. UKA 226 ginocchia (revisione e reintervento), PJI su 71; TKA 6208-6236 ginocchia, PJI su 2107. Età, intervallo fra HTO e conversione, tipo di impianto: non riportati nell'abstract.",results:"UKA dopo HTO: revisione 10,2% (IC 95% 4,5-21,6; I² 61,6%), reintervento 14,4% (9,1-21,9; I² 37,0%), PJI 0-3,3%; miglioramento del Knee Society Score 34,09-38,80 punti. TKA dopo HTO: revisione 5,0% (3,5-7,2; I² 79,5%), reintervento 11,1% (7,3-16,3; I² 92,8%), PJI 2,9% (2,0-4,0; I² 33,5%); miglioramento KSS 25,0-57,0. Studi comparativi diretti (2): nessuna differenza significativa di sopravvivenza o funzione. Dopo il 2020 (esplorativo): revisione 6,3% per UKA e 3,9% per TKA. Causa più frequente di revisione della UKA: progressione laterale dell'artrosi.",concl:"Gli autori: la UKA dopo HTO non è una controindicazione assoluta in pazienti selezionati (artrosi mediale isolata, MCL sufficiente, allineamento residuo accettabile); risultati da leggere come generatori di ipotesi, non come prova di equivalenza né di efficacia comparativa; servono studi prospettici comparativi.",limits:"Confronto UKA-TKA indiretto: solo 2 studi comparativi, gruppi molto sbilanciati (226 contro oltre 6000 ginocchia) · eterogeneità alta nella TKA (I² 79,5% e 92,8%) e intervalli larghi per la UKA (4,5-21,6%) · base prevalentemente retrospettiva; selezione dei pazienti per la UKA non confrontabile con quella per la TKA.",perte:"Fai osteotomie e protesi monocompartimentali: il lavoro dice che, dopo una HTO fallita, la UKA può avere un ruolo in casi molto selezionati, ma con revisioni numericamente più alte della TKA e numeri piccoli. Non muove nessuna tensione."},
{n:4,mono:"m-gray",dot:"green",sec:"res",j:"The Surgeon",h:"LCA con peroneo lungo o hamstring: prelievo più rapido, Lysholm uguale a 12 mesi",v:"RCT monocentrico (Kano, Nigeria) su 162 adulti, 81 per braccio: prelievo del peroneo lungo in 7,13 ± 2,30 min contro 24,37 ± 4,85 min dell'hamstring (p<0,05), innesto più lungo e più spesso, Lysholm a 12 mesi senza differenza (p=0,53); ipotrofia della coscia nel braccio hamstring.",ax:"Soliudeen Adebayo, Abdulfatah Ayokunle, Ibrahim Abolaji",date:"ott 2026",meta:"RCT monocentrico, 162 pazienti (81+81), follow-up 12 mesi, Kano (Nigeria) · [II]",pmid:'42833924',doi:'10.1016/j.surge.2026.09.009',journal:"The surgeon : journal of the Royal Colleges of Surgeons of Edinburgh and Ireland",authors:"Soliudeen Adebayo A, Abdulfatah Ayokunle S, Ibrahim Abolaji A",design:"RCT in un centro ortopedico terziario: adulti con rottura del LCA assegnati a innesto di tendine peroneo lungo (PLT) o di hamstring (HT) in ricostruzione artroscopica. Esiti primari: tempo di prelievo e dimensioni dell'innesto; secondari: Lysholm, score AOFAS, circonferenza della coscia, morbilità del sito di prelievo; controlli a 1, 6 e 12 mesi. Metodo di randomizzazione, occultamento e cecità: non riportati nell'abstract. Testo completo non aperto.",pop:"162 adulti con rottura del LCA: 81 HT e 81 PLT. Età, sesso, lesioni associate: non riportati nell'abstract.",results:"Tempo di prelievo PLT 7,13 ± 2,30 min contro HT 24,37 ± 4,85 min (p<0,05). Innesto PLT più lungo e più spesso (p<0,05; valori non riportati nell'abstract). Lysholm migliorato in entrambi i gruppi, senza differenza a 12 mesi (p=0,53; differenze medie e IC non riportati). AOFAS del gruppo PLT tornato vicino al basale a 6 mesi. Gruppo HT: ipotrofia significativa della coscia e un'infezione del sito chirurgico.",concl:"Gli autori: il peroneo lungo offre prelievo più rapido, innesto più grande e minore morbilità del sito donatore con esiti funzionali precoci comparabili all'hamstring; alternativa affidabile.",limits:"Follow-up di 12 mesi e solo esiti funzionali precoci: rotture dell'innesto, instabilità e rientro allo sport non riportati nell'abstract · un solo centro, metodo di randomizzazione e cecità non riportati · «nessuna differenza» sul Lysholm senza IC non è equivalenza (vedi studio muto) · lo score AOFAS misura il costo al sito donatore, ma l'abstract non dà i valori.",perte:"Non è il tuo innesto: tu usi retto femorale o tendine quadricipitale. Il lavoro mette il peroneo lungo contro l'hamstring, non contro il quadricipite, e non dice nulla sul LET associato. Non muove nessuna tensione."},
{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Robotic Surgery",h:"TKA convenzionale, MAKO o sensori di pressione: nessuna differenza dopo correzione",v:"Coorte retrospettiva monocentrica (Hong Kong) su 173 ginocchia in 139 pazienti (36 convenzionali, 92 MAKO, 45 con sensore Verasense): nessun esito con differenza di gruppo dopo la correzione di Holm; Verasense contro MAKO, dolore aggiustato -0,318 punti (p di Holm 0,2546); dolore a zero in 125 ginocchia su 149 (83,9%).",ax:"Choi, Lam, Zhang, Cao, Mak, Wong, Yung, Ong",date:"set 2026",meta:"coorte retrospettiva monocentrica, 173 ginocchia (139 pazienti), TKA CR convenzionale, MAKO e Verasense · [III]",pmid:'42742643',doi:'10.1007/s11701-026-03954-w',journal:"Journal of robotic surgery",authors:"Choi TL, Lam GY, Zhang X, Cao M, Mak RW, Wong DC, Yung PS, Ong MT",design:"Coorte retrospettiva monocentrica: protesi totale con conservazione del crociato posteriore con tre tecniche (strumentario convenzionale, assistenza robotica MAKO, sensore di pressione Verasense). Modelli aggiustati per valore basale, età, sesso e BMI, con clustering per paziente sui dati del ginocchio; correzione di Holm per famiglia di test; interazioni con la gravità basale post hoc. Testo completo disponibile su PMC, non letto per esteso: numeri dall'abstract.",pop:"173 ginocchia in 139 pazienti: 36 convenzionali, 92 MAKO, 45 Verasense. Età, BMI e follow-up: non riportati nell'abstract.",results:"Nessun esito con differenza di gruppo dopo la correzione di Holm, né nel miglioramento favorevole né nello stato postoperatorio aggiustato. Verasense contro MAKO: miglioramento del dolore 0,769 punti (p di Holm 0,2195), dolore postoperatorio aggiustato -0,318 punti (p di Holm 0,2546); intervalli di confidenza non riportati nell'abstract. Dolore postoperatorio zero in 125 ginocchia su 149 (83,9%).",concl:"Gli autori: nessuna evidenza solida che le tre tecniche si associno a esiti diversi; il quadro Verasense contro MAKO sul dolore genera un'ipotesi e non stabilisce né superiorità né equivalenza.",limits:"Retrospettiva, 36 ginocchia nel braccio convenzionale: il campione non permette di escludere differenze clinicamente rilevanti (vedi studio muto) · assegnazione alla tecnica non randomizzata, confondenti non misurati · follow-up e IC non riportati nell'abstract.",perte:"Operi con il robot VELYS, non con MAKO: il lavoro non lo riguarda direttamente. Arriva però come citante nuovo del verdetto su RACER-Knee (RCT, nessun beneficio clinico a 12 mesi della robotica): è un tassello debole nella stessa direzione, che non lo cambia. Non muove nessuna tensione."},
{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of Magnetic Resonance Imaging",h:"RM prima del LCA: UTE-T2* alto si associa a più sintomi a 11 anni, su 22 pazienti",v:"Coorte retrospettiva su RM acquisita in modo prospettico, 22 pazienti ricostruiti per LCA (2009-2012), controllo a una mediana di 11,3 anni: UTE-T2* più alto di cartilagine femorale mediale profonda e menisco mediale si associa a KOOS Sintomi peggiore (R² aggiustato 0,146-0,332); radiografie in 11 pazienti.",ax:"Williams, Drain, Koltsov, Qian, Stevens, Chu",date:"ott 2026",meta:"coorte retrospettiva su dati di imaging prospettici, 22 pazienti con LCA, Stanford · [III]",pmid:'42830692',doi:'10.1002/jmri.70571',journal:"Journal of magnetic resonance imaging : JMRI",authors:"Williams AA, Drain NP, Koltsov JCB, Qian Y, Stevens KJ, Chu CR",design:"Coorte retrospettiva longitudinale con RM a 3 T (mappe UTE-T2*, sequenza spirale 3D) acquisita prima della ricostruzione del LCA (2009-2012) e confrontata con KOOS Sintomi, Marx e radiografie a 11 anni. Regressione lineare aggiustata per lesione meniscale; Mann-Whitney per lo stato radiografico (Kellgren-Lawrence ≥2). Testo completo non aperto.",pop:"22 partecipanti (13 donne), età media 29 ± 9 anni; KOOS e Marx per tutti, radiografie solo per 11.",results:"UTE-T2* preoperatorio alto di cartilagine femorale mediale profonda e menisco mediale associato a KOOS Sintomi peggiore a 11 anni: R² aggiustato 0,146-0,332 (IC non riportati). Cartilagine femorale e Marx: R² aggiustato 0,208, p=0,056 (tendenza). Menisco posteriore e Marx: R² aggiustato 0,308 (valori più alti, attività più alta). Nel sottogruppo con radiografie (n=11) l'UTE-T2* mediano del menisco posteriore era più alto del 69% nei pazienti con artrosi radiografica.",concl:"Gli autori: l'UTE-T2* preoperatorio di cartilagine e menisco mediali si associa a sintomi e attività a 11 anni; possibile marcatore di pre-artrosi dopo LCA.",limits:"22 pazienti e 11 radiografie: associazioni esplorative, nessuna correzione per test multipli riportata · R² aggiustati modesti, IC non riportati, e una direzione opposta per il menisco posteriore · nessun confronto con RM convenzionale né dato su un uso clinico del marcatore (vedi studio muto).",perte:"Non è una tecnica che usi: è un marcatore di imaging che non cambia l'indicazione né la scelta dell'innesto. Interessa se un giorno la RM potrà dire quali ginocchi con LCA vanno verso l'artrosi. Non muove nessuna tensione."},
{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Sports Health",h:"LCA e salute mentale: diagnosi preesistente peggiora KOOS solo a 2 settimane",v:"Coorte retrospettiva su 365 adulti operati di LCA (2016-2023): 50 (13,7%) con diagnosi di salute mentale preesistente, KOOS peggiore a 2 settimane e senza differenze dopo; 8 su 315 (2,5%) senza storia hanno ricevuto una nuova diagnosi entro 1 anno, più spesso dopo infortuni non sportivi (7% contro 1,6%; p=0,02).",ax:"Devoy, Lamonica, Toole, DelRegno, Belal, Bisson, Bisson, Haider, Wind",date:"ott 2026",meta:"coorte retrospettiva monocentrica, 365 pazienti con LCA, Buffalo (USA) · [III]",pmid:'42830691',doi:'10.1177/19417381261486640',journal:"Sports health",authors:"Devoy E, Lamonica L, Toole T, DelRegno P, Belal K, Bisson A, Bisson L, Haider MN, Wind WM",design:"Coorte retrospettiva: adulti sottoposti a ricostruzione del LCA fra ottobre 2016 e ottobre 2023 in una grande struttura universitaria; PROMIS Global Health e KOOS prima e dopo l'intervento. Diagnosi di salute mentale da farmaci, codici ICD-10 o note di cartella. Modelli lineari misti aggiustati per sesso. Testo completo non aperto.",pop:"365 pazienti: 50 (13,7%) con diagnosi preesistente (età media 36,4 anni, 84,0% donne); 315 senza storia (32,9 anni, 52,7% donne). Infortuni sportivi 294, non sportivi 71.",results:"Gruppo con diagnosi preesistente: PROMIS Mental Health basale 47,3 contro 53,6 (p<0,001); KOOS peggiore a 2 settimane, nessuna differenza dopo. Nuove diagnosi a 1 anno: 8 su 315 (2,5%). Infortuni non sportivi contro sportivi: KOOS e PROMIS basali più bassi e nuove diagnosi 7% contro 1,6% (p=0,02). Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: oltre le 2 settimane i KOOS non differiscono per diagnosi preesistente; gli infortuni non sportivi si associano a più nuove diagnosi; i dati possono aiutare a individuare chi ha bisogno di sostegno.",limits:"Retrospettiva con diagnosi ricavate da cartella, 50 pazienti nel gruppo esposto, solo 8 eventi nuovi (vedi studio muto) · gruppi diversi per età e sesso nonostante l'aggiustamento per sesso · nessun dato sull'innesto, sul tempo al rientro allo sport e sulla gestione psicologica.",perte:"Non tocca una tecnica: dice che il peso della salute mentale preesistente sul KOOS è breve e che gli infortuni non sportivi meritano attenzione. Utile al colloquio pre-operatorio, non cambia il gesto chirurgico. Non muove nessuna tensione."},
{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"The Journal of Knee Surgery",h:"Tibia della TKA: lo stelo centrale nella chiglia non cambia le revisioni",v:"Registro australiano (AOANJRR) su 76.710 TKA cementate minimamente stabilizzate (1999-2023): revisione complessiva HR 1,05 (IC 95% 0,74-1,48; p=0,779) fra chiglia con stelo centrale e componente solo con alette (Triathlon, Stryker); nelle donne con componente solo alette HR 1,33 (1,01-1,75; p=0,045).",ax:"Kannan, Lewis, Holder, Corfield, Roheet, McMahon",date:"ott 2026",meta:"registro nazionale (AOANJRR), 76.710 TKA cementate primarie, follow-up medio 5,6 anni · [III]",pmid:'42833280',doi:'10.1055/a-2908-1829',journal:"The journal of knee surgery",authors:"Kannan A, Lewis P, Holder C, Corfield S, Roheet V, McMahon SJ",design:"Analisi retrospettiva del registro nazionale australiano (AOANJRR): TKA primarie cementate, minimamente stabilizzate, senza prolungamenti di stelo, per artrosi primaria, da settembre 1999 a dicembre 2023. Confronto fra due basi tibiali Triathlon (Stryker): chiglia standard con stelo centrale e alette, contro solo alette. Kaplan-Meier per la revisione cumulativa; hazard ratio aggiustati per sesso ed età; stratificazione per sesso, BMI e conformità dell'inserto. Testo completo non aperto.",pop:"76.710 TKA; età media 69,3 ± 8,9 anni; 59,6% donne; follow-up medio 5,6 anni. Numero di impianti per base: non riportato nell'abstract.",results:"Revisione per qualunque causa: HR 1,05 (IC 95% 0,74-1,48; p=0,779). Revisione per mobilizzazione: nessuna differenza «con i numeri disponibili» (HR non riportato nell'abstract). Stratificazione per sesso, BMI e inserto (CR e condylar-stabilizing): nessuna differenza, tranne le donne con solo alette: HR 1,33 (IC 95% 1,01-1,75; p=0,045).",concl:"Gli autori: lo stelo centrale nella chiglia delle basi tibiali cementate non modifica la sopravvivenza delle TKA minimamente stabilizzate.",limits:"L'intervallo 0,74-1,48 non esclude un rischio di revisione fino a circa il 48% più alto con le sole alette, né uno più basso (vedi studio muto) · l'unico risultato significativo viene da una stratificazione, con p=0,045 e più confronti, senza correzione dichiarata · dati di registro: scelta dell'impianto non randomizzata, numero di eventi per mobilizzazione non riportato.",perte:"È un impianto Stryker, non DePuy Synthes: non è una componente che usi con il VELYS. Dice che, a 5-6 anni, lo stelo centrale non sposta il rischio di revisione in un grande registro. Non muove nessuna tensione."}];

var SUGGQ=[{"k": "kol", "n": "J. L. Rocha de Faria (Rio de Janeiro, Brasile)", "w": "Rio de Janeiro, Brasile: primo autore della nota tecnica di oggi sulla sutura meniscale continua ibrida (PMID 42831213; afferenza letta nei metadati PubMed: Istituto nazionale di traumatologia e ortopedia del Brasile, e Università di San Paolo), insieme a C. P. Helito, già nella tua rete. Corrispondenza tecnica con le tue suture meniscali. Sostituisce C. Batailler (5 ottobre, nessun segnale dell'utente arrivato per farla ruotare)."}];

var BRIEF_TEXT="Oggi, martedì 6 ottobre, otto lavori e nessuna scheda rossa né arancione: nessun richiamo di dispositivi nuovo, nessuna ritrattazione che ti riguardi, nessun nuovo consensus o linea guida. Il lavoro del giorno è una meta-analisi di nove studi randomizzati, su Arthroscopy, sui biologici usati per aumentare la ricostruzione del crociato: plasma ricco di piastrine, midollo osseo concentrato e cellule staminali. Su cinquecentoquarantatré pazienti, il Lysholm con il plasma, il KOOS con il midollo e l'allargamento del tunnel non differiscono, con valori di p fra 0,35 e 0,95; in sei studi su nove anche la maturazione dell'innesto è simile, e nessuna complicanza è riportata. Tu non usi biologici, e il tipo di innesto non è riportato nell'abstract. Il limite: eterogeneità alta, I al quadrato del 77% e dell'87%, pochi studi per ogni biologico, nessun esito duro e intervalli esposti su una scala poco chiara; nessuna differenza non è equivalenza. Tra le altre schede: una revisione narrativa sul Journal of Bone and Joint Surgery conferma che nelle lesioni radicolari del menisco la riparazione si associa a esiti migliori della meniscectomia, ma senza un protocollo riabilitativo condiviso e senza numeri nell'abstract. Una meta-analisi di quarantuno studi sulla protesi dopo osteotomia fallita: revisione del 10,2% con la parziale, intervallo da 4,5 a 21,6, contro il 5,0% con la totale, ma il confronto è indiretto. Un RCT nigeriano su centosessantadue pazienti: peroneo lungo contro hamstring, prelievo in sette minuti contro ventiquattro e Lysholm uguale a un anno; non è il tuo innesto. Una coorte di Hong Kong su centosettantatré protesi totali, convenzionali, MAKO o con sensore: nessuna differenza dopo la correzione, in debole coerenza con RACER-Knee. Nessuna tensione si sposta.";

var BRIEF_DIALOGO=[{"chi": "A", "t": "Oggi, martedì 6 ottobre: otto lavori, nessuna scheda rossa né arancione, nessun richiamo nuovo e nessuna ritrattazione che ti riguardi."}, {"chi": "B", "t": "E il lavoro del giorno?"}, {"chi": "A", "t": "Una meta-analisi di nove studi randomizzati su Arthroscopy: aggiungere biologici alla ricostruzione del crociato, cioè plasma ricco di piastrine, midollo osseo concentrato o cellule staminali. Cinquecentoquarantatré pazienti in tutto."}, {"chi": "B", "t": "E funzionano?"}, {"chi": "A", "t": "Lysholm con il plasma, KOOS con il midollo e allargamento del tunnel non cambiano: p fra 0,35 e 0,95. In sei studi su nove anche la maturazione dell'innesto è simile, e nessuna complicanza."}, {"chi": "B", "t": "Quindi niente vantaggio."}, {"chi": "A", "t": "Attenzione: gli studi sono pochi e diversi fra loro, con eterogeneità alta, e nessun esito duro nell'abstract. Nessuna differenza non è equivalenza. Un vantaggio non è dimostrato, ma non è nemmeno escluso."}, {"chi": "B", "t": "E per te?"}, {"chi": "A", "t": "Non usi biologici, e il tipo di innesto negli studi non è riportato nell'abstract, quindi non sappiamo se valga per il quadricipite."}, {"chi": "B", "t": "Il resto della giornata?"}, {"chi": "A", "t": "Una revisione narrativa sulla radice meniscale: la riparazione si associa a esiti migliori della meniscectomia nei pazienti selezionati, ma non c'è un protocollo riabilitativo condiviso. Poi una meta-analisi sulla protesi dopo osteotomia fallita: revisione del 10,2% con la parziale, intervallo da 4,5 a 21,6, contro il 5,0% con la totale, ma il confronto è indiretto."}, {"chi": "B", "t": "E il crociato con il peroneo?"}, {"chi": "A", "t": "Un RCT nigeriano su centosessantadue pazienti: prelievo del peroneo lungo in sette minuti contro ventiquattro per l'hamstring, Lysholm uguale a un anno. Non è il tuo innesto."}, {"chi": "B", "t": "E la robotica?"}, {"chi": "A", "t": "Una coorte di Hong Kong su centosettantatré protesi totali: nessuna differenza fra tecnica convenzionale, MAKO e sensore dopo la correzione, in debole coerenza con RACER-Knee. Nessuna tensione si sposta."}];

